'use strict';
// Sidebar sections and pages modelled on what ISPman offered, backed by netops' own data: customers by type,
// hotspot and PPPoE packages/sessions/logs, vouchers, manual connects, SMS campaigns and revenue reports.
(()=>{
const S='hs-sessions pp-sessions hs-auth pp-auth hs-acct pp-acct hs-requests hs-manual hs-vouchers comms-campaigns pay-reports'.split(' ');
const PRESETS={
 'cust-new':{title:'New customers',desc:'Customers added in the last 7 days.',tab:'subscribers',pred:s=>Date.now()-s.created<7*864e5},
 'cust-inactive':{title:'Inactive customers',desc:'Expired or suspended accounts. Hotspot is blocked; PPPoE lands on the payment page.',tab:'subscribers',pred:s=>s.state!=='active'},
 'cust-hotspot':{title:'Hotspot customers',desc:'Customers who log in through the hotspot portal.',tab:'subscribers',pred:s=>s.service==='hotspot'},
 'cust-pppoe':{title:'PPPoE customers',desc:'Home and business customers who connect with PPPoE.',tab:'subscribers',pred:s=>s.service==='pppoe'},
 'hs-packages':{title:'Hotspot packages',desc:'Packages shown on the hotspot landing page.',tab:'plans',planPred:p=>p.service!=='pppoe'},
 'pp-packages':{title:'PPPoE packages',desc:'Speeds and prices for home and business customers.',tab:'plans',planPred:p=>p.service!=='hotspot'},
 'pay-received':{title:'Payments received',desc:'Every payment recorded: M-Pesa, cash and bank.',tab:'payments'},
 'pay-mpesa':{title:'M-Pesa & portal',desc:'Daraja keys, paybill C2B and the landing page.',tab:'mpesa'},
 'comms-sms':{title:'SMS',desc:'Provider, automatic messages and the SMS log.',tab:'sms'}
};
const group=(id,label,glyph,head)=>head?[id,label,glyph,head]:[id,label,glyph];
const items=[
 group('radius','All customers & plans','onu','CUSTOMERS'),group('cust-new','New customers','plus'),group('cust-inactive','Inactive','clock'),group('cust-hotspot','Hotspot customers','activity'),group('cust-pppoe','PPPoE customers','router'),
 group('hs-packages','Packages','server','HOTSPOT'),group('hs-requests','Payment requests','check'),group('hs-sessions','Sessions','activity'),group('hs-auth','Auth logs','info'),group('hs-acct','Acct logs','info'),group('hs-manual','Manual connect','plus'),group('hs-vouchers','Vouchers','server'),
 group('pp-packages','Packages','server','PPPOE'),group('pp-sessions','Sessions','activity'),group('pp-auth','Auth logs','info'),group('pp-acct','Acct logs','info'),
 group('pay-received','Received','check','PAYMENTS'),group('pay-reports','Reports','grid'),group('pay-mpesa','M-Pesa & portal','settings'),
 group('comms-sms','SMS','info','COMMS'),group('comms-campaigns','Campaigns','activity')
];
const at=nav.findIndex(n=>n[0]==='radius');if(at>=0)nav.splice(at,1,...items);
const d=nav.findIndex(n=>n[0]==='dashboard');if(d>=0)nav.splice(d+1,0,['trends','Trends','activity']);
window.radiusPreset=id=>PRESETS[id]||null;
const svcOf=id=>id.startsWith('hs-')?'hotspot':'pppoe',H=s=>escapeHtml(String(s??'')),csvCell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';
function shell(title,desc,actions=''){$('#main').innerHTML=heading(title,desc,actions)+'<div id="im-body"><div class="card"><p class="muted" style="padding:20px">Loading…</p></div></div>';}
const guard=(id,fn)=>async()=>{try{await fn();}catch(e){if(state.page===id)$('#im-body').innerHTML=notice('Could not load this page',H(e.message),true);}};
const svcBadge=s=>s==='pppoe'?'PPPoE':'Hotspot';
const sessionTable=(list,ended)=>table(['SUBSCRIBER','IP / MAC','ROUTER','STARTED',ended?'ENDED':'LAST UPDATE','DOWNLOADED','UPLOADED'],list,s=>`<tr><td><strong>${H(s.username)}</strong></td><td>${H(s.ip||'—')}<small>${H(s.mac||'')}</small></td><td>${H(s.nas)}</td><td>${H(stamp(s.startedAt))}</td><td>${H(stamp(ended?s.stoppedAt:s.updatedAt))}${ended&&s.cause?`<small>${H(s.cause)}</small>`:''}</td><td>${bytesShort(s.downloadBytes)}</td><td>${bytesShort(s.uploadBytes)}</td></tr>`,'Nothing here yet.');
const pages={
 async sessions(id){const svc=svcOf(id);shell(svc==='hotspot'?'Hotspot sessions':'PPPoE sessions','Connected now, and recently ended sessions.');
  const o=await api('radius');if(state.page!==id)return;$('#im-body').innerHTML=`<section class="card sites-panel"><div class="card-header"><div><h2>Online now (${o.sessions.filter(s=>s.service===svc).length})</h2><p>Reported by the routers in the last 15 minutes.</p></div></div>${sessionTable(o.sessions.filter(s=>s.service===svc),false)}</section><section class="card sites-panel"><div class="card-header"><div><h2>Recent sessions</h2><p>Ended sessions from the last 30 days.</p></div></div>${sessionTable(o.history.filter(s=>s.service===svc),true)}</section>`;},
 async auth(id){const svc=svcOf(id);shell(svc==='hotspot'?'Hotspot auth logs':'PPPoE auth logs','Every login attempt and why it was accepted or rejected (latest 500).');
  const o=await api('radius');if(state.page!==id)return;$('#im-body').innerHTML=`<section class="card sites-panel">${table(['TIME','LOGIN','RESULT','REASON','ROUTER / MAC'],o.log.filter(l=>l.service===svc),l=>`<tr><td>${H(stamp(l.time))}</td><td><code>${H(l.username)}</code></td><td><span class="status ${l.result==='accept'?'online':'offline'}">${l.result==='accept'?'Accepted':'Rejected'}</span></td><td>${H(l.reason)}</td><td>${H(l.nas)}<small>${H(l.mac||'')}</small></td></tr>`,'No logins yet.')}</section>`;},
 async acct(id){const svc=svcOf(id);shell(svc==='hotspot'?'Hotspot acct logs':'PPPoE acct logs','Start, interim and stop records sent by the routers (latest 500).');
  const o=await api('radius');if(state.page!==id)return;const label={start:'Start',interim:'Interim',stop:'Stop'};$('#im-body').innerHTML=`<section class="card sites-panel">${table(['TIME','USER','EVENT','IP / MAC','ROUTER','SESSION TIME','DOWN / UP'],o.acct.filter(a=>a.service===svc),a=>`<tr><td>${H(stamp(a.time))}</td><td><code>${H(a.username)}</code></td><td>${label[a.status]||H(a.status)}${a.cause?`<small>${H(a.cause)}</small>`:''}</td><td>${H(a.ip||'—')}<small>${H(a.mac||'')}</small></td><td>${H(a.nas)}</td><td>${a.seconds?Math.round(a.seconds/60)+' min':'—'}</td><td>${bytesShort(a.download)} / ${bytesShort(a.upload)}</td></tr>`,'No accounting records yet.')}</section>`;},
 async requests(id){shell('Payment requests','M-Pesa requests started from the hotspot portal (latest 300).');
  const m=await api('mpesa');if(state.page!==id)return;const st={pending:'Waiting',paid:'Paid',failed:'Failed'};$('#im-body').innerHTML=`<section class="card sites-panel">${table(['TIME','PHONE','FOR','AMOUNT','STATUS','RECEIPT / REASON'],m.payments,p=>`<tr><td>${H(stamp(p.createdAt))}</td><td>${H(p.phone)}</td><td>${H(p.planName||p.kind||'')}</td><td>${ksh(p.amount)}</td><td><span class="status ${p.status==='paid'?'online':p.status==='pending'?'warning':'offline'}">${st[p.status]||H(p.status)}</span></td><td>${H(p.receipt||p.reason||'')}</td></tr>`,'No requests yet.')}</section>`;},
 async manual(id){shell('Manual connect','Give a walk-in customer a hotspot code without a payment prompt. Record cash under Payments if you took it.');
  const o=await api('radius'),plans=o.plans.filter(p=>p.service!=='pppoe');if(state.page!==id)return;
  $('#im-body').innerHTML=plans.length?`<section class="card"><form id="im-manual" class="radius-form"><div class="form-grid"><label>Package<select name="planId">${plans.map(p=>`<option value="${H(p.id)}">${H(p.name)} · ${ksh(p.price)}</option>`).join('')}</select></label><label>Customer name (optional)<input name="name" maxlength="80"></label><label>Phone (optional)<input name="phone" maxlength="20" placeholder="07…"></label></div><label class="check-label"><input type="checkbox" name="sms"> SMS the code to this phone</label><button class="button primary">Create code</button></form></section>`:notice('No hotspot packages','Create a hotspot package first.',true);
  const f=$('#im-manual');if(f)f.onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(f)),b=$('button',f);b.disabled=true;try{const r=await api('radius/manual-connect','POST',{planId:v.planId,name:v.name,phone:v.phone,sms:v.sms==='on'});showDetails('Hotspot code',`<p>Give this to the customer. It works as both username and password on the WiFi page.</p><p style="font-size:2rem;text-align:center"><code>${H(r.code)}</code></p><p class="muted">${H(r.plan)} · active until ${H(stamp(r.expiresAt))}${r.sms?' · SMS '+H(r.sms.status):''}</p>`);f.reset();}catch(error){toast(error.message);}finally{b.disabled=false;}};},
 async vouchers(id){shell('Vouchers','Prepaid hotspot codes. The time starts the first time a customer logs in with the code, so unsold vouchers never expire.');
  const [o,v]=await Promise.all([api('radius'),api('radius/vouchers')]);if(state.page!==id)return;const plans=o.plans.filter(p=>p.service!=='pppoe');
  $('#im-body').innerHTML=`<section class="card"><form id="im-vgen" class="radius-form"><div class="form-grid"><label>Package<select name="planId">${plans.map(p=>`<option value="${H(p.id)}">${H(p.name)} · ${ksh(p.price)}</option>`).join('')}</select></label><label>How many<input name="count" type="number" min="1" max="500" value="20"></label><label>Code length<select name="length"><option>6</option><option selected>8</option><option>10</option></select></label><label>Batch name (optional)<input name="name" maxlength="60"></label></div><button class="button primary" ${plans.length?'':'disabled'}>Generate vouchers</button></form></section><section class="card sites-panel">${table(['BATCH','PACKAGE','CREATED','UNUSED','USED','ACTIONS'],v.batches,b=>`<tr><td><strong>${H(b.name)}</strong></td><td>${H(b.planName)}</td><td>${H(stamp(b.createdAt))}</td><td>${b.unused}</td><td>${b.used}</td><td><div class="row-actions"><button class="button secondary" data-vcsv="${b.id}">Download CSV</button>${b.unused?`<button class="button secondary" data-vdel="${b.id}">Delete unused</button>`:''}</div></td></tr>`,'No voucher batches yet.')}</section>`;
  const download=async(batchId,name)=>{const r=await api('radius/vouchers/'+batchId),csv='code,status,used_at,used_by\n'+r.codes.map(c=>[c.code,c.status,c.usedAt?new Date(c.usedAt).toISOString():'',c.usedBy].map(csvCell).join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='vouchers-'+String(name).replace(/[^\w.-]+/g,'-')+'.csv';a.click();URL.revokeObjectURL(a.href);};
  const f=$('#im-vgen');f.onsubmit=async e=>{e.preventDefault();const x=Object.fromEntries(new FormData(f)),b=$('button',f);b.disabled=true;try{const r=await api('radius/vouchers','POST',{planId:x.planId,count:Number(x.count),length:Number(x.length),name:x.name});toast(r.codes.length+' vouchers created');await download(r.batch.id,r.batch.name);pages.vouchers(id);}catch(error){toast(error.message);b.disabled=false;}};
  for(const b of document.querySelectorAll('[data-vcsv]'))b.onclick=()=>download(b.dataset.vcsv,v.batches.find(x=>x.id===b.dataset.vcsv).name).catch(e=>toast(e.message));
  for(const b of document.querySelectorAll('[data-vdel]'))b.onclick=async()=>{if(!confirm('Delete the unused vouchers in this batch? Used ones stay.'))return;try{await api('radius/vouchers/'+b.dataset.vdel,'DELETE');pages.vouchers(id);}catch(e){toast(e.message);}};},
 async campaigns(id){shell('SMS campaigns','Send one message to a group of customers. Messages go out slowly in the background; you can stop a run.');
  const [o,c]=await Promise.all([api('radius'),api('radius/campaign')]);if(state.page!==id)return;const labels={all:'Everyone',active:'Active customers',expired:'Expired customers',expiring3:'Expiring within 3 days',hotspot:'Hotspot customers',pppoe:'PPPoE customers',plan:'One package'},run=c.campaign;
  $('#im-body').innerHTML=`<section class="card"><form id="im-camp" class="radius-form"><div class="form-grid"><label>Send to<select name="segment">${c.segments.map(s=>`<option value="${s}">${labels[s]}</option>`).join('')}</select></label><label id="im-plan" hidden>Package<select name="planId">${o.plans.map(p=>`<option value="${H(p.id)}">${H(p.name)}</option>`).join('')}</select></label></div><label>Message <small class="muted">({name} and {username} are filled in; 459 characters at most)</small><textarea name="message" rows="4" maxlength="459" required></textarea></label><p class="muted" id="im-count">Choose who to send to.</p><button class="button primary" id="im-send" disabled>Send campaign</button></form></section>
  <section class="card" id="im-run">${run?`<div class="radius-form"><h2>Last campaign</h2><p>${H(stamp(run.startedAt))} · ${H(labels[run.segment]||run.segment)} · <strong>${run.state==='sending'?'Sending…':run.state==='done'?'Done':'Stopped'}</strong></p><p>${run.sent} sent, ${run.failed} failed of ${run.total}</p><p class="muted">${H(run.message)}</p>${c.running?'<button class="button secondary" id="im-stop">Stop sending</button>':''}</div>`:'<p class="muted" style="padding:20px">No campaigns yet.</p>'}</section>`;
  const f=$('#im-camp'),count=$('#im-count'),send=$('#im-send');let n=0;
  const preview=async()=>{const v=Object.fromEntries(new FormData(f));$('#im-plan').hidden=v.segment!=='plan';try{const r=await api('radius/campaign/preview','POST',{segment:v.segment,planId:v.planId});n=r.count;count.textContent=n?`${n} customer${n===1?'':'s'} with a phone number will receive this${r.sample.length?' (e.g. '+r.sample.join(', ')+')':''}.`:'Nobody with a phone number matches.';send.disabled=!n||c.running;}catch(e){n=0;count.textContent=e.message;send.disabled=true;}};
  f.segment.onchange=preview;if(f.planId)f.planId.onchange=preview;preview();
  f.onsubmit=async e=>{e.preventDefault();if(!confirm(`Send this SMS to ${n} customer${n===1?'':'s'}?`))return;const v=Object.fromEntries(new FormData(f));send.disabled=true;try{await api('radius/campaign','POST',{segment:v.segment,planId:v.planId,message:v.message,confirm:n});toast('Campaign started');pages.campaigns(id);}catch(error){toast(error.message);send.disabled=false;}};
  const stop=$('#im-stop');if(stop)stop.onclick=async()=>{try{await api('radius/campaign','DELETE');toast('Stopping after the current message');}catch(e){toast(e.message);}};
  if(c.running)setTimeout(()=>{if(state.page===id&&!$('dialog[open]'))pages.campaigns(id);},4000);},
 async reports(id){const days=Number(sessionStorage.getItem('imDays'))||30;shell('Reports','Revenue and growth from recorded payments.',`<select id="im-days" aria-label="Period">${[7,30,90,365].map(n=>`<option value="${n}" ${n===days?'selected':''}>Last ${n} days</option>`).join('')}</select>`);
  const r=await api('reports?days='+days);if(state.page!==id)return;
  const stat=(t,v,s)=>`<div class="card metric-card"><div><div class="metric-title">${t}</div><strong class="metric-value">${v}</strong><p>${s}</p></div></div>`,money=n=>'KSh '+Number(n).toLocaleString('en-KE'),tbl=(t,list)=>`<section class="card sites-panel"><div class="card-header"><h2>${t}</h2></div>${table(['NAME','AMOUNT','SHARE'],list,x=>`<tr><td>${H(x.name)}</td><td>${money(x.amount)}</td><td>${r.total?Math.round(x.amount/r.total*100):0}%</td></tr>`,'No payments in this period.')}</section>`;
  $('#im-body').innerHTML=`<div class="dashboard-cards sites-cards">${stat('Revenue',money(r.total),`Last ${r.days} days`)}${stat('Payments',r.count,'Recorded')}${stat('Average payment',money(r.average),'Per payment')}${stat('New customers',r.newCustomers,`${r.newHotspot} hotspot · ${r.newPppoe} PPPoE`)}</div><section class="card kd" style="padding-bottom:0"><div class="card-header"><h2>Revenue per day</h2></div><div id="im-chart" class="kd-chart"></div></section>${tbl('By package',r.byPlan)}${tbl('By payment method',r.byMethod)}`;
  kc.bars($('#im-chart'),{items:r.perDay.map(x=>({label:x.date.slice(days>31?5:8),title:x.date,value:x.amount,sub:money(x.amount)})),label:'Revenue per day',fmt:v=>money(v)});
  $('#im-days').onchange=e=>{sessionStorage.setItem('imDays',e.target.value);pages.reports(id);};}
};
const ROUTES={'hs-sessions':'sessions','pp-sessions':'sessions','hs-auth':'auth','pp-auth':'auth','hs-acct':'acct','pp-acct':'acct','hs-requests':'requests','hs-manual':'manual','hs-vouchers':'vouchers','comms-campaigns':'campaigns','pay-reports':'reports'};
const original=window.render;
window.render=function(){
 const id=state.page,preset=PRESETS[id];
 if(id==='radius'){radiusView.pred=radiusView.planPred=null;radiusView.tab=radiusView.tab||'subscribers';}
 if(preset){radiusView.pred=preset.pred||null;radiusView.planPred=preset.planPred||null;radiusView.tab=preset.tab;chrome();renderRadius();$('#breadcrumb').textContent=nav.find(n=>n[0]===id)?.[1]||id;const hd=$('#main h1');if(hd){hd.textContent=preset.title;hd.nextElementSibling.textContent=preset.desc;}for(const el of document.querySelectorAll('.sites-tabs'))el.hidden=true;const m=$('#radius-metrics');if(m)m.style.display='none';return;}
 if(ROUTES[id]){chrome();$('#breadcrumb').textContent=nav.find(n=>n[0]===id)?.[1]||id;guard(id,()=>pages[ROUTES[id]](id))();return;}
 if(id==='trends'){chrome();$('#breadcrumb').textContent='Trends';kd.range='7d';kd.first=true;return renderDashboard();}
 return original();
};
// Counts beside the menu items.
let counts={};
function badges(){for(const [id,key] of Object.entries({radius:'customers','cust-inactive':'inactive','cust-hotspot':'hotspot','cust-pppoe':'pppoe','hs-sessions':'onlineHotspot','pp-sessions':'onlinePppoe'})){const a=document.querySelector(`#navigation a[href="#${id}"]`),n=counts[key];if(a&&n&&!a.querySelector('.nav-number'))a.insertAdjacentHTML('beforeend',`<span class="nav-number">${n}</span>`);}}
const chromeOriginal=window.chrome;window.chrome=function(){chromeOriginal();badges();};
async function loadCounts(){if(!state.session?.user||state.session.user.role==='installer'||document.hidden)return;try{counts=await api('nav-counts');badges();}catch{}}
setInterval(loadCounts,60000);setTimeout(loadCounts,1500);
})();
